/** Our categories, each with its subcategory list pages (live counts). Same
    section and card markup as the seller's "By Demographic" block. */
function OurCategories() {
  const hub = Route.useLoaderData();
  return (
    <>
      {hub.categories.map((c, i) => (
        <section key={c.code} id={c.code} className={`py-12 lg:py-16${i % 2 === 0 ? " bg-muted/30" : ""}`}>
          <div className="container mx-auto max-w-6xl px-4">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 rounded-lg bg-primary/10 text-primary"><Library className="h-5 w-5" /></div>
              <h2 className="text-2xl font-bold">{c.name}</h2>
              <div className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80">{c.subs.length} lists</div>
            </div>
            <p className="text-muted-foreground mb-6">{c.subs.reduce((n, s) => n + s.count, 0)} ideas across {c.subs.length} lists</p>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {c.subs.map((s) => (
                <a key={s.code} className="block group" href={`/lists/${s.slug}`}>
                  <div className="rounded-lg border bg-card text-card-foreground shadow-sm premium-card h-full hover:border-primary/50 hover:-translate-y-0.5 transition-all">
                    <div className="p-4">
                      <h3 className="font-semibold text-base mb-1 group-hover:text-primary transition-colors text-balance">{s.name}</h3>
                      <div className="flex items-center justify-between text-sm text-muted-foreground">
                        <span className="flex items-center gap-1"><List className="h-3.5 w-3.5" />{s.count} ideas</span>
                        <ChevronRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />
                      </div>
                    </div>
                  </div>
                </a>
              ))}
            </div>
          </div>
        </section>
      ))}
    </>
  );
}

/** Complete index of every subcategory list page, alphabetical. */
function OurIndex() {
  const hub = Route.useLoaderData();
  const all = hub.categories.flatMap((c) => c.subs).sort((a, b) => a.name.localeCompare(b.name));
  return (
    <section id="all-lists" className="py-12 lg:py-16 border-t border-border scroll-mt-24">
      <div className="container mx-auto max-w-6xl px-4">
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2 rounded-lg bg-primary/10 text-primary"><Library className="h-5 w-5" /></div>
          <h2 className="text-2xl font-bold">Complete index — every list</h2>
          <div className="inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80">{all.length}</div>
        </div>
        <p className="text-muted-foreground mb-6 text-sm">Alphabetical index of all {all.length} list pages on BusinessIdea.io.</p>
        <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-6 gap-y-1.5 text-sm">
          {all.map((s) => (
            <li key={s.code}>
              <a className="text-foreground/80 hover:text-primary hover:underline underline-offset-4 transition-colors" href={`/lists/${s.slug}`}>{s.name}</a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

function ListsPage() {
  return (
    <V2Frame active="/lists">
      <Section01 />
      <Section02 />
      <Section03 />
      <Section04 />
      <Section05 />
      <Section06 />
      <Section07 />
      <OurCategories />
      <Section14 />
      <Section15 />
      <OurIndex />
      <Section17 />
      <Section18 />
      <Section19 />
      <Section20 />
    </V2Frame>
  );
}
